                values: new object[,]
                {
                    { new Guid("10000000-0000-0000-0000-000000000006"), "Поколения 0–2 используют гипотезу о короткой жизни большинства объектов; крупные объекты попадают в LOH. Server GC создаёт heap и поток сборки на логический процессор и ориентирован на throughput, Workstation — на отзывчивость. Начинать нужно с allocation rate, % Time in GC, pause duration, размера поколений и LOH, затем подтверждать причину через dotnet-counters, trace или dump.", "Как устроены поколения GC, Server GC и Workstation GC, и по каким метрикам вы будете искать причину длинных пауз?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000007"), "Pinned-объект нельзя перемещать при compaction, поэтому множество долгоживущих закреплений фрагментирует heap и повышает стоимость GC. Pinning оправдан на короткой границе с native API или I/O; для долгих буферов лучше использовать специализированные пулы, pinned object heap либо unmanaged memory и явно контролировать время жизни.", "Почему длительное pinning управляемой памяти опасно и когда без него всё же не обойтись?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000008"), "При starvation запросы ждут свободный worker, latency растёт, а CPU может оставаться умеренным; типичные причины — sync-over-async, блокирующие I/O и долгие locks. Проверяют очередь ThreadPool, число потоков, request latency и stacks через dotnet-counters, dotnet-stack или trace. Исправление — асинхронность по всей цепочке, устранение блокировок и ограничение параллелизма, а не бездумное увеличение MinThreads.", "Как диагностировать ThreadPool starvation в ASP.NET Core и чем он отличается от высокой загрузки CPU?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000009"), "ValueTask полезен в очень горячем API, которое часто завершается синхронно и где измерения показывают значимые аллокации Task. Его нельзя бездумно await-ить несколько раз, хранить или комбинировать как обычный Task; часто требуется AsTask. По умолчанию предпочтителен Task, а ValueTask вводят только после профилирования и с ясным контрактом.", "Когда ValueTask оправдан, а когда он только усложняет код?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000010"), "Ковариантный out-параметр позволяет использовать источник более конкретного типа как источник базового, например IEnumerable<Dog> как IEnumerable<Animal>. Контравариантный in-параметр позволяет обработчику базового типа обслуживать конкретный, например IComparer<Animal> для Dog. Вариантность безопасна только для ссылочных типов и ограничивает позиции чтения и записи параметра.", "Объясните ковариантность и контравариантность generic-интерфейсов на практическом примере.", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000011"), "Если Equals возвращает true, hash code обязан совпадать; обратное не требуется. Поля, участвующие в равенстве и hash code, нельзя менять, пока объект служит ключом, иначе запись станет логически недоступной. Для value object обычно задают структурное равенство, а entity сравнивают по устойчивой идентичности с осторожностью до её назначения.", "Какие требования связывают Equals, GetHashCode и использование объекта как ключа Dictionary?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000012"), "Класс должен освобождать только ресурсы, которыми владеет, быть устойчивым к повторному Dispose и не выполнять работу после освобождения. IAsyncDisposable нужен, когда корректное закрытие требует async I/O; комбинированный тип обычно реализует оба пути и подавляет финализацию. Финализатор нужен только при прямом владении unmanaged-ресурсом, предпочтительно через SafeHandle.", "Как правильно проектировать IDisposable и IAsyncDisposable для класса с несколькими ресурсами?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000013"), "lock подходит для короткой синхронной критической секции без await. SemaphoreSlim позволяет асинхронно ограничивать конкуренцию, ReaderWriterLockSlim полезен лишь при измеренном преобладании чтений и достаточной длительности операций. Channel<T> часто лучше общей блокировки, когда задачу можно представить как очередь с одним или несколькими потребителями и backpressure.", "Как выбрать между lock, SemaphoreSlim, ReaderWriterLockSlim и Channel<T>?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000014"), "volatile задаёт семантику чтения и записи с барьерами видимости, но не делает составные операции вроде increment атомарными и не защищает инвариант нескольких полей. Interlocked подходит для атомарных операций над отдельным значением. Если переход состояния затрагивает несколько значений или требует проверки-изменения, нужен lock либо другая синхронизация.", "Что гарантирует volatile, а что требует Interlocked или lock?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000015"), "Снимок полностью строят до публикации, не изменяют после неё и заменяют ссылку атомарно через Volatile.Write или Interlocked.Exchange. Читатели получают локальную копию ссылки через Volatile.Read и работают без блокировок. Важно, чтобы весь достижимый граф действительно был immutable, иначе безопасная публикация корня не устраняет внутренние гонки.", "Как избежать гонок при публикации immutable-снимка конфигурации между потоками?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000016"), "Reflection усложняет trimming/AOT, переносит ошибки в runtime и в горячих путях добавляет lookup, boxing и invocation overhead. Метаданные можно кэшировать, вызовы компилировать в delegates, а для сериализации, DI-регистрации и маппинга использовать source generators. Замена оправдана после измерений либо когда нужна статическая проверяемость и Native AOT.", "Когда reflection становится архитектурной или производительной проблемой и чем её заменить?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000017"), "Tiered compilation быстро запускает код и затем перекомпилирует горячие методы; dynamic PGO использует фактический профиль для специализации. Native AOT уменьшает startup и footprint, но ограничивает динамическую генерацию кода и reflection-сценарии. Поэтому оптимизируют по реальному режиму деплоя, прогревают benchmark и проверяют совместимость библиотек.", "Чем Tiered Compilation, dynamic PGO и Native AOT меняют подход к оптимизации .NET-приложения?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000018"), "Publisher хранит сильную ссылку на delegate, а delegate — на subscriber, поэтому долгоживущий publisher удерживает подписчика. Нужно явно отписываться, возвращать IDisposable-токен подписки, привязывать время жизни объектов или применять weak-event только при понятной семантике. Анонимная lambda усложняет отписку, если её экземпляр не сохранён.", "Почему подписка на event может вызвать утечку памяти?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000019"), "Создание и обработка исключения существенно дороже обычной ветки и искажает telemetry, если ожидаемые ситуации выглядят как ошибки. Для вероятного неуспеха лучше Try-методы, Result или явный union. Исключение остаётся правильным для нарушения контракта и действительно исключительного состояния, особенно когда вызывающий уровень может восстановиться.", "Почему исключения не подходят для обычного управления потоком в горячем коде?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000020"), "NRT — статический анализ аннотаций, а не runtime-защита: он уменьшает число случайных null, но внешние данные, reflection, старые библиотеки и неверный оператор ! могут нарушить контракт. На границах всё равно нужна runtime-валидация. Аннотации следует согласовывать с доменной семантикой, а не отключать предупреждения массовыми подавлениями.", "Что реально дают nullable reference types и где остаются границы их гарантий?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000021"), "Lambda, захватывающая локальные переменные или this, обычно создаёт объект closure и delegate; в цикле это может стать заметным allocation rate. Помогают static lambda, передача state отдельным параметром и кэширование delegate. Но решение принимают по профилю или BenchmarkDotNet, потому что читаемость важнее микроскопической экономии вне горячего пути.", "Какие скрытые аллокации создают closures и как проверить, что оптимизация действительно нужна?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000022"), "Запрос выполняется при перечислении, поэтому повторное перечисление может повторить дорогой I/O или увидеть уже изменённое состояние. Возврат ленивой последовательности за пределы lifetime DbContext приводит к сбоям, а side effects внутри Select делают поведение неочевидным. Границу материализации выбирают явно и документируют одноразовые последовательности.", "Какие ошибки возникают из-за deferred execution в LINQ?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000023"), "Возвращаемый Task завершается после всех операций; при ошибках он Faulted, а Exception содержит aggregate внутренних ошибок, хотя await обычно пробрасывает одну. Остальные ошибки нужно анализировать через сам Task. Отмена не прекращает уже запущенную работу автоматически: всем операциям передают общий token и отдельно решают политику частичного результата.", "Как Task.WhenAll сообщает об ошибках и отмене нескольких операций?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000024"), "Используют bounded Channel или очередь с ограниченной ёмкостью, чтобы быстрый producer ждал либо применял явную политику drop. Число consumers ограничивают по характеру работы, ошибки и завершение канала распространяют явно, CancellationToken проходит по всей цепочке. Метрики глубины очереди и времени ожидания показывают, где находится bottleneck.", "Как спроектировать ограниченный асинхронный pipeline с backpressure?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000025"), "SafeHandle инкапсулирует критический handle, корректно взаимодействует с GC и гарантирует освобождение даже при исключениях и сложной финализации. Собственный финализатор удлиняет жизнь объекта и легко содержит race или double-free. Управляемый wrapper обычно владеет SafeHandle и реализует Dispose без собственной небезопасной логики финализации.", "Почему SafeHandle предпочтительнее собственного финализатора для native-ресурса?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000026"), "Generic-код со значимым типом обычно работает без упаковки благодаря специализации runtime. Boxing возникает при приведении к object или интерфейсу, использовании негeneric API, некоторых вызовах constrained-методов и форматировании. Проверяют allocations профилировщиком; constraints и generic-интерфейсы помогают сохранить статический тип.", "Где generics устраняют boxing, а где boxing всё равно появляется?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000027"), "in и ref readonly позволяют передавать или возвращать ссылку без права изменения, что может снизить копирование крупных struct. scoped ограничивает escape ссылки временем жизни текущего scope и помогает компилятору предотвращать висячие ссылки. Для маленьких struct косвенный доступ может быть не быстрее, поэтому выбор подтверждают benchmark.", "Для чего нужны in, ref readonly и scoped и какие риски они уменьшают?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000028"), "Value object делают неизменяемым, валидируют при создании и определяют равенство по всем значимым компонентам. Он не должен иметь отдельного жизненного цикла или изменяемой идентичности. Неизменяемость упрощает совместное использование между потоками, но вложенные коллекции тоже должны быть immutable или защищённо скопированы.", "Как спроектировать тип value object, чтобы он оставался корректным в многопоточном и доменном коде?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000029"), "Блокировка потока до завершения async-операции может вызвать классический deadlock при захваченном context, а на сервере — ThreadPool starvation и резкий рост latency. Исключения также оборачиваются иначе. Правильное решение — async all the way; синхронную границу оставляют только при контролируемом startup-коде и ясных ограничениях.", "Что такое sync-over-async и почему .Result или .Wait опасны даже без SynchronizationContext?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000030"), "Повторяют только транзиентные и идемпотентные операции, используют ограниченное число попыток, exponential backoff с jitter и общий timeout. CancellationToken должен прекращать ожидание. Retry без лимита создаёт retry storm, поэтому его сочетают с circuit breaker, ограничением конкуренции и наблюдаемостью причин.", "Как проектировать retry для асинхронной операции, чтобы не усугубить отказ?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000031"), "Локальное время неоднозначно при переходах DST и зависит от timezone машины. Для событий и хранения обычно используют UTC через DateTimeOffset и внедряемый TimeProvider, а локализацию выполняют на границе отображения. Для измерения длительности нужен монотонный Stopwatch, потому что wall clock может корректироваться.", "Какие проблемы создаёт DateTime.Now в распределённой системе?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000032"), "Для симуляций и некритичных значений используют Random.Shared, который безопасен для параллельного доступа. Токены, пароли, nonce и идентификаторы безопасности требуют RandomNumberGenerator. Seeded Random полезен для воспроизводимых тестов, но его предсказуемость делает его непригодным для защиты.", "Как безопасно использовать Random в конкурентном приложении и когда нужен криптографический генератор?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000033"), "Внутри catch оператор throw сохраняет исходный stack trace, а throw ex его повреждает. Filter when позволяет классифицировать исключение без входа в catch и не меняет исходный стек; в нём не должно быть side effects. Перехватывают исключение только если добавляют контекст, выполняют восстановление или переводят его на осмысленную границу.", "Как правильно повторно выбросить исключение и когда полезны exception filters?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000034"), "Обычный массив проще и безопаснее для долгоживущих данных. ArrayPool снижает давление на GC для частых временных буферов, но арендованный массив может быть больше запрошенного, содержит старые данные и обязан возвращаться в finally; чувствительные данные очищают. MemoryPool удобен для ownership-модели и pipelines, особенно с нестандартной памятью.", "Как выбрать между ArrayPool<T>, MemoryPool<T> и обычным массивом?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000035"), "Независимые значения в одной cache line заставляют ядра постоянно инвалидировать кэш друг друга, поэтому масштабирование ухудшается без логической блокировки. Это видно в высококонкурентных счётчиках и массивах состояния. Помогают разбиение счётчиков, локальная агрегация и иногда padding, но подтверждать причину нужно аппаратными метриками и benchmark.", "Что такое false sharing и как оно проявляется в .NET?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000036"), "BackgroundService должен уважать stoppingToken, не запускать fire-and-forget работу без учёта и завершать приём новых задач до дренирования текущих. На остановке учитывают host shutdown timeout, корректно закрывают каналы и освобождают ресурсы. Необработанная ошибка фоновой задачи должна быть наблюдаемой и иметь явную политику остановки или восстановления.", "Как организовать graceful shutdown фоновых задач в Generic Host?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000037"), "Вызывающий код не наблюдает завершение и исключение, а захваченные scoped-сервисы могут быть уже освобождены. Задачу следует await-ить, передать управляемому background queue или зарегистрировать у компонента, который наблюдает результат и остановку. Если отделение намеренное, нужны собственный scope, logging, timeout и политика ошибок.", "Почему fire-and-forget Task часто приводит к потерянным ошибкам и повреждению lifetime?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000038"), "Value factory может выполниться несколько раз параллельно, хотя в словарь попадёт одно значение, поэтому она не должна иметь необратимых side effects. Для единственного вычисления хранят Lazy<T> или Task<T> с подходящим режимом синхронизации и решают, удалять ли faulted/cancelled значение для повторной попытки.", "Как безопасно кэшировать данные с помощью ConcurrentDictionary.GetOrAdd при дорогой фабрике?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000039"), "Он позволяет отдавать элементы по мере готовности без материализации всей коллекции и поддерживает естественный backpressure на уровне MoveNextAsync. Нужно передавать отмену через WithCancellation или EnumeratorCancellation, корректно освобождать enumerator и помнить, что ошибки могут возникнуть в середине перечисления. Источник не следует перечислять конкурентно без явного контракта.", "Чем IAsyncEnumerable<T> полезен для потоковой обработки и какие обязанности он добавляет?", "CSharp" },
                    { new Guid("10000000-0000-0000-0000-000000000040"), "Сначала разделяют managed heap, native memory, working set и кэши, наблюдая тренд после полных GC. Затем сравнивают heap dumps, ищут доминирующие типы и цепочки удержания, проверяют event subscriptions, static roots, timers и незавершённые Tasks. Важно воспроизвести нагрузку и доказать удержание объектов, а не судить только по диспетчеру задач.", "Как вы будете расследовать рост памяти в .NET-сервисе, не предполагая заранее утечку?", "CSharp" },
                    { new Guid("20000000-0000-0000-0000-000000000006"), "Single query может породить cartesian explosion при нескольких коллекциях Include и передать много дублированных данных. Split query выполняет несколько SQL-запросов и уменьшает дублирование, но добавляет roundtrips и без подходящей транзакции может увидеть несогласованные снимки. Выбор делают по форме графа, объёму данных и измеренному SQL.", "Когда split query лучше single query и какой новый риск он создаёт?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000007"), "Вместо Skip страница фильтруется по последнему уникально упорядоченному ключу, например CreatedAt < cursorDate либо лексикографической паре CreatedAt/Id. База продолжает чтение с позиции индекса и не пересчитывает все предыдущие строки. Нужен стабильный уникальный порядок и составной индекс, совпадающий с фильтром и сортировкой.", "Как реализовать keyset pagination в EF Core и почему она устойчивее Offset/Limit?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000008"), "Pooling переиспользует экземпляры DbContext и уменьшает стоимость инициализации, но OnConfiguring обычно выполняется один раз. В context нельзя хранить request-specific состояние, tenant id или изменяемые флаги без гарантированного сброса. Пул не делает DbContext потокобезопасным и не заменяет pooling соединений драйвера.", "Что даёт DbContext pooling и какие данные нельзя оставлять в pooled context?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000009"), "Compiled query уменьшает overhead анализа expression tree и поиска в query cache в очень горячем повторяющемся запросе одной формы. Она не меняет план базы, индексы, число строк или network latency. Сначала оптимизируют SQL и roundtrips, затем benchmark показывает, значима ли доля самого EF.", "Когда compiled query имеет смысл и почему она не исправит медленный SQL?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000010"), "Константы, динамически встроенные в expression tree, создают новые формы запросов и могут загрязнять кэши EF и БД. Значения нужно передавать как параметры, а динамические фильтры строить со стабильной структурой. Query cache hit rate и SQL-логи помогают увидеть постоянную перекомпиляцию.", "Как форма LINQ-выражения влияет на query cache и план-кэш базы?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000011"), "DetectChanges сравнивает tracked-граф с original values и при большом числе сущностей вызывается многократно некоторыми API. Для контролируемого bulk-сценария его временно отключают, добавляют данные пакетами и вызывают DetectChanges явно перед SaveChanges. Это требует аккуратности: иначе изменения или связи могут не сохраниться.", "Почему AutoDetectChanges может стать bottleneck при массовой загрузке?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000012"), "Они формируют set-based SQL и не загружают сущности в память, поэтому эффективны для массовых изменений. Операция обходит ChangeTracker, доменные методы и его текущее состояние; tracked-объекты могут стать устаревшими. Инварианты, concurrency и транзакционную границу нужно обеспечить явно.", "Чем ExecuteUpdate/ExecuteDelete отличаются от изменения загруженных entities?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000013"), "Retry должен повторять весь логический блок как единицу, иначе состояние после частичного выполнения неопределённо. Пользовательскую транзакцию создают внутри ExecuteAsync выбранной strategy и делают операции идемпотентными либо проверяемыми. Нельзя просто обернуть SaveChanges retry, если рядом есть внешние side effects.", "Как execution strategy с retry взаимодействует с пользовательской транзакцией?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000014"), "Один вызов SaveChanges обычно выполняется атомарно в транзакции провайдера. Явная транзакция нужна, когда единый инвариант охватывает несколько SaveChanges, raw SQL или другие операции той же БД. Её держат короткой; внешние HTTP или broker-вызовы внутрь не помещают, применяя outbox.", "Какие гарантии даёт SaveChanges и когда нужна явная транзакция?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000015"), "Перед SaveChanges EF может создать savepoint, чтобы при ошибке откатить только этот вызов и оставить транзакцию в пригодном состоянии, например для разрешения concurrency conflict. Поддержка зависит от провайдера и настроек. Это не заменяет общую обработку ошибки и решение, можно ли безопасно продолжать.", "Для чего EF Core создаёт savepoint внутри существующей транзакции?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000016"), "Сначала определяют бизнес-политику: client wins, store wins или merge отдельных полей. Затем получают database values, обновляют original values и повторяют ограниченное число раз только безопасную транзакцию. Слепой retry без повторной проверки инварианта может перезаписать чужое изменение.", "Как корректно разрешать DbUpdateConcurrencyException?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000017"), "Для набора полей используют owned или complex type, а для одного столбца — value converter. Изменяемому преобразованному типу часто нужен ValueComparer, иначе ChangeTracker не увидит изменение. Конструктор и приватные свойства позволяют сохранить валидацию, но EF materialization не должен создавать недопустимое состояние.", "Как маппить value object, сохраняя его доменную семантику?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000018"), "TPH хранит иерархию в одной таблице, обычно быстрее читает, но имеет nullable-столбцы и широкий ряд. TPT нормализует типы, однако сложные запросы требуют множества joins. TPC дублирует базовые столбцы и хорошо читает конкретные типы, но усложняет общие ключи и изменения схемы. Выбор подтверждают реальными запросами.", "Какие компромиссы у TPH, TPT и TPC наследования?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000019"), "Не следует принимать entity целиком и помечать её Modified. Загружают агрегат, применяют валидированную команду через доменные методы и сохраняют изменённые поля; для patch явно перечисляют разрешённые изменения. Concurrency token защищает от lost update, а DTO отделяет контракт от persistence-модели.", "Как избежать случайной перезаписи полей при disconnected update из API?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000020"), "Tenant filter должен использовать контекстное значение безопасного scoped-сервиса и применяться ко всем tenant-owned сущностям. Нельзя доверять tenant id из произвольного payload; его получают из проверенной identity. Административный IgnoreQueryFilters изолируют, тестируют обходы и учитывают, что pooled DbContext требует особой передачи tenant state.", "Как проектировать global query filter для multi-tenancy?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000021"), "Нужны глобальные фильтры, правила уникальности только среди активных строк, каскадная семантика, аудит и политика физической очистки. IgnoreQueryFilters может случайно вернуть удалённые данные, а навигации — дать неожиданный результат. Для некоторых данных temporal/audit table или отдельный статус жизненного цикла честнее.", "Почему soft delete сложнее простого поля IsDeleted?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000022"), "Interceptor полезен для cross-cutting concerns: telemetry, command tagging, connection hooks или построение outbox на SaveChanges. Бизнес-решения и изменения агрегатов в нём становятся неявными и зависят от порядка вызовов. Interceptor должен быть детерминированным, быстрым и иметь тесты на retry и транзакции.", "Когда interceptor EF Core уместен, а когда он скрывает бизнес-логику?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000023"), "Значения всегда параметризуют через FromSqlInterpolated или параметры провайдера. Имена таблиц, колонок и направление сортировки параметризовать нельзя, поэтому их выбирают только из whitelist, а не из пользовательской строки. Нужно понимать composability запроса и не полагаться на escaping как на полноценную защиту.", "Как безопасно использовать FromSql и динамические части SQL?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000024"), "Он не проверяет SQL translation, ограничения, транзакции, collation, null semantics и поведение конкретного провайдера. Для unit-тестов домена база не нужна; для persistence-тестов используют реальный engine в контейнере или SQLite только если его различия допустимы. Критичные запросы тестируют на production-провайдере.", "Почему InMemory provider плохо имитирует реляционную базу в интеграционных тестах?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000025"), "Применяют expand-contract: сначала добавляют совместимую nullable/default колонку, разворачивают код с dual read/write или backfill, затем переключают чтение и только в следующем релизе удаляют старую. Долгие index build и table rewrite планируют отдельно. Миграции не должны предполагать мгновенное обновление всех экземпляров.", "Как подготовить zero-downtime миграцию для переименования обязательной колонки?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000026"), "Несколько экземпляров могут одновременно менять схему, блокировать startup и получить разные результаты при частичной ошибке. Production-миграции лучше выполнять отдельным контролируемым job с правами DDL, backup и наблюдаемостью. Автомиграция удобна для локального MVP, но это осознанное ограничение окружения.", "Почему автоматический Database.Migrate на старте опасен в нескольких production-инстансах?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000027"), "Начинают с сгенерированного SQL и плана базы: порядок фильтров в LINQ сам по себе не задаёт порядок индекса. Проектируют индекс по equality/range predicates, sort и selectivity, при необходимости include/partial возможности провайдера. Затем измеряют чтения и latency на репрезентативных данных.", "Как связать LINQ-запрос с нужным индексом, не пытаясь дать EF hint?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000028"), "JOIN двух sibling-коллекций создаёт произведение их строк: 10 элементов одной и 10 другой дают 100 строк на корень, хотя объектов меньше. Это увеличивает сеть и materialization. Помогают проекция, split query, отдельные запросы или изменение read model.", "Что такое cartesian explosion при нескольких Include коллекций одного уровня?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000029"), "Batch уменьшает roundtrips, но слишком большой пакет увеличивает SQL, параметры, locks, memory и время транзакции. Провайдер имеет собственные пределы и heuristics. Измеряют throughput и p95 на реальной сети; для очень больших загрузок используют bulk/native copy, staging table или set-based команды.", "Как выбрать размер batch при SaveChanges и массовых операциях?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000030"), "Современный EF обычно выбрасывает исключение вне верхней client projection, чтобы не загрузить таблицу незаметно. Нужно переписать выражение в поддерживаемую форму, вынести вычисление после узкой материализации или добавить mapping database function. AsEnumerable ставят только после явного ограничения данных.", "Что происходит, когда часть LINQ-выражения не переводится в SQL?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000031"), "Проецируют сразу в DTO только нужные поля, применяют фильтр и пагинацию до materialization, используют AsNoTracking и избегают Include, если Select уже выражает форму. Это уменьшает данные, ChangeTracker и coupling. Сгенерированный SQL и число roundtrips всё равно проверяют.", "Как проектировать read-only запрос с большим графом без materialization доменных entities?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000032"), "Если read-only результат содержит повторные ссылки на одну сущность, обычный no-tracking создаст несколько экземпляров. Identity resolution использует временный tracker только для материализации и возвращает единые ссылки без дальнейшего tracking. Это расходует дополнительные ресурсы, поэтому не нужно для плоской DTO-проекции.", "Когда AsNoTrackingWithIdentityResolution полезнее AsNoTracking?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000033"), "Owned dependents внутри агрегата логично удалять вместе с root, и cascade отражает это правило. Между агрегатами database cascade может удалить данные без доменной проверки и создать длинные блокировки; чаще используют Restrict и отдельный use case. Поведение EF и самой БД нужно согласовать.", "Как каскадное удаление связано с границами агрегата?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000034"), "Domain events преобразуют в outbox rows и добавляют в тот же DbContext до SaveChanges, чтобы данные и намерение публикации зафиксировались одной транзакцией. Отдельный worker публикует их с retry и помечает обработанными. Получатель остаётся идемпотентным, потому что crash между publish и отметкой создаёт дубликат.", "Как хранить outbox-сообщения вместе с агрегатом через EF Core?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000035"), "DbContext уже реализует Unit of Work и repository-подобный доступ. Универсальный CRUD-интерфейс часто скрывает возможности LINQ, допускает операции вне агрегата и разрастается спецификациями. Репозиторий оправдан как доменный контракт для aggregate roots; read side может использовать специализированные queries.", "Почему DbContext не следует прятать за generic repository во всех случаях?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000036"), "JSON удобен для атомарного вложенного документа с изменяемой схемой и редкими междокументными связями. Нужно проверить поддержку provider для query/update, индексы по путям и change tracking. Если поля участвуют в constraints, joins, частых частичных обновлениях или независимом жизненном цикле, нормализованная модель обычно прозрачнее.", "Как моделировать JSON-колонку и когда нормализация лучше?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000037"), "Отдельный read DbContext направляют на replica только для tolerant-to-staleness сценариев. После команды пользователь может читать primary, передавать consistency token/временное окно или ждать позиции репликации. Routing нельзя скрывать полностью: use case должен знать требуемую консистентность.", "Как организовать чтение с replica, не нарушив read-your-writes?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000038"), "Кэшируют DTO/read model, задают ключ с tenant и параметрами, ограниченный TTL и размер. Для важных обновлений используют invalidation/event version, но принимают возможность гонки. Кэш не должен возвращать tracked entities и не заменяет корректный источник истины.", "Как кэшировать результаты EF-запросов без выдачи устаревших критичных данных?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000039"), "Коррелируют trace запроса с EF command activity, фиксируют SQL, параметры, число roundtrips и время ожидания соединения. В базе анализируют actual plan, rows, buffers, locks и статистику; отдельно измеряют materialization и serialization. Оптимизацию начинают с доминирующего участка, а не с LINQ-косметики.", "Как диагностировать медленный запрос EF Core от HTTP до базы?", "EntityFramework" },
                    { new Guid("20000000-0000-0000-0000-000000000040"), "Если экран постоянно требует тяжёлых joins, денормализации, истории или иной формы данных, сложность и нагрузка сигнализируют о специализированной проекции. Read model обновляют синхронно в той же БД либо асинхронно с явной eventual consistency. Это компромисс между скоростью чтения, свежестью и операционной сложностью.", "Когда нужен отдельный read model вместо всё более сложного EF-запроса по write model?", "EntityFramework" },
                    { new Guid("30000000-0000-0000-0000-000000000006"), "Ack сообщает broker, что consumer принял ответственность за доставку после успешной обработки. Confirm сообщает publisher, что broker принял ответственность за publish; для quorum queue — после репликации кворумом. Они защищают разные участки пути, а неопределённый исход при разрыве всё равно требует повторной отправки и идемпотентности.", "Чем consumer acknowledgements отличаются от publisher confirms и почему нужны оба механизма?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000007"), "Durable сохраняет определение очереди, persistent просит сохранить сообщение, но publisher не знает, успел ли broker безопасно принять его без confirms. На consumer-side ранний auto-ack также теряет сообщение при crash. Полная схема включает durable replicated queue, publisher confirms, manual ack после side effect и обработку неопределённых исходов.", "Почему durable queue и persistent message ещё не гарантируют отсутствие потерь?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000008"), "Quorum queue нужна для репликации, предсказуемого leader election и высокой сохранности данных; она подтверждает publish после кворума. Цена — дополнительная latency, disk и network overhead, отсутствие transient/exclusive сценариев и ограничения для огромных backlog. Временные очереди, минимальная latency или очень длинные логи могут требовать classic queue или stream.", "Когда quorum queue предпочтительнее classic queue?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000009"), "Без кворума очередь не может безопасно подтвердить новые записи и сохранить consistency, поэтому publish не получает успешный confirm либо блокируется/завершается ошибкой согласно клиенту и timeout. Система выбирает сохранность данных вместо availability. Producer должен ограниченно повторить неопределённые сообщения после восстановления и не считать timeout доказательством отсутствия записи.", "Что происходит с publish во время недоступности большинства реплик quorum queue?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000010"), "Сообщение получает устойчивый MessageId или business operation id. В одной локальной транзакции consumer фиксирует id в inbox/processed table с unique constraint и применяет изменение; дубликат превращается в no-op. Ack отправляют после commit, а срок хранения ключей выбирают по максимальному окну повторной доставки.", "Как спроектировать идемпотентный consumer с базой данных?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000011"), "Broker не может атомарно согласовать ack с произвольным side effect в другой системе. Crash после commit, но до ack, приводит к redelivery; confirm может потеряться после принятого publish. Практическая модель — at-least-once transport плюс идемпотентная обработка, deduplication и бизнес-операции с устойчивым ключом.", "Почему exactly-once delivery обычно является ложной целью в RabbitMQ-интеграции?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000012"), "Prefetch ограничивает число unacked сообщений на consumer. Для CPU-bound обычно начинают около числа параллельных workers, для I/O-bound допускают больше, учитывая latency и connection limits. Большое значение повышает throughput, но увеличивает memory, время redelivery и несправедливость; настраивают по processing time, backlog и p95.", "Как выбрать prefetch для CPU-bound и I/O-bound consumer?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000013"), "Сообщение немедленно возвращается в ту же очередь и снова попадает тому же или другому consumer, потребляя CPU и network без паузы. Лучше ограничивать попытки, направлять в delay/retry queue с TTL или delayed mechanism и после лимита — в DLQ. Причину и attempt count сохраняют в headers/metadata.", "Как retry через nack/requeue может создать hot loop?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000014"), "Consumer различает транзиентную и постоянную ошибку, ограничивает число повторов и переносит неисправимое сообщение в DLQ вместе с причиной и correlation metadata. Нужны alert, инструмент просмотра и контролируемый replay после исправления. Бесконечный requeue скрывает проблему и блокирует полезную нагрузку.", "Какова безопасная модель обработки poison message?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000015"), "В classic queue сообщение за большим TTL в голове может задержать истёкшие сообщения позади него, а dead-lettering по умолчанию может иметь weaker guarantees. Создают отдельные retry buckets с фиксированными TTL, контролируют размер и используют quorum at-least-once dead lettering, если нужна сохранность. Для сложного расписания лучше внешний scheduler.", "Какие риски у TTL + dead-letter exchange как механизма задержки?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000016"), "Publisher ставит mandatory и обрабатывает basic.return, одновременно используя confirms. Alternate exchange может собирать нерутируемые сообщения, но это другая бизнес-политика и требует мониторинга. Confirm означает принятие broker, а не обязательно попадание в ожидаемую очередь, поэтому оба сигнала различают.", "Как гарантировать, что unroutable message не исчезнет незаметно?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000017"), "Нужно понимать, что старые channels закрыты, in-flight confirms и deliveries имеют неопределённый исход, а topology recovery не восстанавливает внешние side effects. Producer повторяет неподтверждённое с idempotency id, consumer остаётся идемпотентным. Connection и channel lifecycle централизуют, recovery события и время недоступности наблюдают.", "Что должна делать .NET-служба при автоматическом recovery соединения RabbitMQ?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000018"), "AMQP channel — логическая сессия с порядком frames и delivery tags; многие client operations не рассчитаны на конкурентную запись. Перемешивание publish frames или confirm state приводит к protocol errors и неверной корреляции. Используют channel per worker, ограниченный pool или сериализованный publisher согласно гарантиям клиента.", "Почему нельзя совместно использовать один channel между конкурентными publisher без синхронизации?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000019"), "Publisher отслеживает monotonically increasing publish sequence number и хранит диапазоны outstanding сообщений. Ack/nack может иметь multiple=true и закрывать все sequence до указанного. Структура должна эффективно удалять диапазон, а при connection loss все оставшиеся считаются неопределёнными и могут быть повторены.", "Как коррелировать publisher confirms с исходными сообщениями при batch publish?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000020"), "Stream хранит append-only log, поддерживает replay по offset, несколько независимых читателей и очень большой backlog. Это подходит event log, fan-out и аналитической обработке. Очередь лучше для распределения задач, удаления после ack и сложной routing-семантики; operational модель и client API различаются.", "Когда streams RabbitMQ лучше очередей?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000021"), "Глобальный порядок теряется, но сохраняется внутри partition. Routing key должен стабильно отправлять связанные события, например одного aggregate id, в одну partition. Число partition определяет параллелизм и стоимость, а consumer group распределяет их между экземплярами; hotspot key всё ещё ограничивает throughput.", "Как partitioning через super streams влияет на порядок сообщений?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000022"), "Контракт должен быть backward/forward совместим: добавляют optional поля с defaults, не меняют смысл существующих и версионируют breaking event type. Consumer применяет tolerant reader и тестируется на старых payload. Envelope содержит event type, schema version, id, causation/correlation и occurred time, но не должен скрывать бизнес-семантику.", "Как проектировать schema evolution сообщений?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000023"), "Domain event отражает внутреннюю модель и может меняться вместе с ней. Integration event — стабильный внешний контракт, минимально раскрывающий данные и часто строящийся после commit. Разделение уменьшает coupling, позволяет обогащать и версионировать сообщение, не публикуя внутренние классы агрегата.", "Почему domain event и integration event не обязаны быть одним типом?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000024"), "Outbox атомарно сохраняет бизнес-изменение и сообщение в одной БД. Dispatcher публикует его и только после confirm отмечает отправленным; crash между этими действиями создаёт повторный publish. Поэтому outbox предотвращает потерю намерения, confirms подтверждают broker, а idempotent consumer закрывает дубликаты.", "Как transactional outbox сочетается с publisher confirms?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000025"), "События маршрутизируют по aggregate id в фиксированную partition/queue и обрабатывают её последовательно одним активным consumer, а разные ключи — параллельно. Альтернатива — version check и буферизация out-of-order, что сложнее. Один глобальный consumer сохраняет порядок, но уничтожает масштабирование.", "Как масштабировать consumers, сохраняя последовательность событий одного агрегата?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000026"), "Нужны rates publish/deliver/ack, число unacked, age старейшего сообщения, redelivery rate, consumer utilization, disk/memory alarms, confirm latency и connection/channel churn. Depth без входного и выходного rate не показывает, растёт ли backlog. Метрики связывают с SLO времени обработки, а не только с размером очереди.", "Какие метрики RabbitMQ важнее простого queue depth?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000027"), "Сравнивают arrival rate и sustainable processing rate, возраст старейшего сообщения и прогноз drain time. Плановый burst с уменьшающимся age может быть нормальным, постоянный рост age при насыщенных consumers — деградация. Также проверяют poison loop, downstream latency, prefetch и resource alarms broker.", "Как отличить здоровый backlog от деградации системы?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000028"), "Broker применяет flow control и блокирует publishing connections, чтобы защитить процесс и данные; consumers обычно могут продолжать дренировать очереди. Producer обязан иметь timeout, bounded buffer и telemetry, иначе блокировка распространится на приложение. Устраняют первопричину capacity/backlog, а не просто повышают порог.", "Что происходит при memory или disk alarm в RabbitMQ?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000029"), "Создание connection дорого, создаёт churn, нагрузку и может само усугубить отказ. Долгоживущие connections переиспользуют, а health проверяет состояние лёгким способом и различает readiness от liveness. Недоступность broker не всегда должна рестартовать процесс; это зависит от способности сервиса буферизовать или деградировать.", "Почему health check, который открывает новое соединение на каждый запрос, вреден?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000030"), "Сначала прекращают принимать новые deliveries или отменяют consumer, затем ждут завершения in-flight в пределах timeout и отправляют ack/nack. Channel закрывают после handlers, connection — последним. Если timeout истёк, незавершённые unacked доставки вернутся в очередь, поэтому обработка обязана быть идемпотентной.", "Как настроить graceful shutdown consumer?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000031"), "Большие сообщения увеличивают memory, disk I/O, replication traffic, latency и время redelivery. В broker и client задают разумный limit; крупный blob кладут в object storage, а в сообщение — ссылку, checksum и metadata с контролем lifetime и доступа. Компрессия помогает сети, но добавляет CPU и риск decompression bomb.", "Как ограничить размер сообщения и почему большие payload вредны для broker?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000032"), "Одно событие должно выражать атомарный бизнес-факт, но transport batch может объединять публикацию или обработку ради throughput. Огромный business batch усложняет retry: одна плохая запись повторяет всё. Если пакет неизбежен, нужна стратегия частичного результата, idempotency каждого элемента и ограничения размера.", "Как выбрать granularity сообщения для пакетной обработки?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000033"), "Unique inbox key в БД остаётся источником истины, потому что broker redelivery и network partition допускают конкуренцию. Операцию выполняют в транзакции после успешной вставки ключа либо используют version/unique business constraint. Распределённый lock редко заменяет идемпотентность и добавляет собственные failure modes.", "Как защититься от duplicate consumer execution одновременно на двух узлах?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000034"), "Он даёт активного consumer с автоматическим failover и удобен, когда очередь должна обрабатываться последовательно. Цена — ограниченный throughput и пауза при переключении; порядок всё равно зависит от requeue и publisher routing. Для масштабирования по ключу лучше несколько partition с SAC на каждой.", "Когда Single Active Consumer полезен?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000035"), "Приоритет позволяет срочным сообщениям обгонять обычные, но слишком много уровней увеличивает внутренние структуры и CPU. Постоянный поток высокого приоритета может вызвать starvation низкого. Часто прозрачнее иметь несколько очередей с отдельными capacity/SLO и управляемым распределением consumers.", "Как приоритетные очереди влияют на fairness и производительность?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000036"), "Каждая очередь хранит состояние, метаданные, процессы и метрики; quorum queue добавляет replicas и consensus overhead. Огромная topology увеличивает recovery time и операционную сложность. Разделение делают по независимому backlog, SLA, retention или ownership, а не по каждому типу сообщения автоматически.", "Почему большое количество очередей и bindings является архитектурным решением, а не бесплатной абстракцией?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000037"), "Команда выражает намерение конкретному владельцу и может быть отклонена; событие сообщает свершившийся факт и не адресует единственного исполнителя. Название, routing, retry и ожидания ответа различаются. Маскировка команды под событие создаёт скрытую оркестрацию и неясную ответственность.", "Как отличить команду от события в messaging-контракте?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000038"), "Если вызывающий блокируется в ожидании немедленного ответа, broker добавляет latency, correlation state, timeout и failure modes, но не даёт преимуществ асинхронности. Для короткого запроса часто лучше HTTP/gRPC. Messaging request/reply оправдан при buffering, изоляции или долгом workflow, причём timeout не отменяет уже принятую работу.", "Когда request/reply поверх RabbitMQ является плохим выбором?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000039"), "Интеграционные тесты должны убивать consumer после commit до ack, разрывать connection до confirm, давать duplicate/out-of-order payload, заполнять DLQ и имитировать недоступный downstream. Проверяют инварианты и отсутствие потери, а не только happy path. Для quorum queue отдельно тестируют потерю leader и кворума.", "Как тестировать отказоустойчивость RabbitMQ-интеграции?", "RabbitMQ" },
                    { new Guid("30000000-0000-0000-0000-000000000040"), "Минимально: message id, type/version, occurred time, correlation id, causation id и trace context; tenant и actor добавляют только при необходимости и с учётом безопасности. Processing span связывают с publish span, но consumer создаёт новый span link/parent согласно семантике. Payload и персональные данные не логируют без контроля.", "Какие данные нужны в message envelope для наблюдаемости и трассировки?", "RabbitMQ" },
                    { new Guid("40000000-0000-0000-0000-000000000006"), "Долгая transaction snapshot удерживает xmin, поэтому версии строк, потенциально видимые ей, нельзя удалить. Dead tuples накапливаются, таблицы и индексы раздуваются, планы и I/O ухудшаются, а wraparound risk растёт. Ищут age транзакций и idle in transaction sessions, ограничивают timeout и сокращают бизнес-операции внутри транзакции.", "Почему длинная транзакция мешает VACUUM и чем это проявляется?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000007"), "Обычный VACUUM помечает место reusable и обновляет visibility map без возврата файла ОС; он допускает параллельную работу. VACUUM FULL переписывает таблицу, возвращает место, но берёт сильную блокировку. Autovacuum выполняет регулярную очистку/analyze и anti-wraparound; его чаще настраивают, а не отключают.", "Чем VACUUM, VACUUM FULL и autovacuum отличаются по назначению?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000008"), "HOT возможен, когда изменяемые колонки не участвуют в индексах и новая версия строки помещается на той же heap page; тогда не создаются новые записи во всех индексах. Пониженный fillfactor оставляет место для обновлений, уменьшая index bloat, но увеличивает размер таблицы. Эффект проверяют по статистике HOT updates и характеру нагрузки.", "Что такое HOT update и как fillfactor влияет на него?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000009"), "Индекс наиболее эффективен, когда ведущие колонки ограничены equality, затем идёт range/sort; правило не сводится к selectivity одного поля. Он может обслужить left prefix и порядок ORDER BY. Проектирование зависит от реальных predicates, частоты запросов и write cost, а не от создания всех комбинаций.", "Как составной B-tree индекс связан с порядком колонок и условиями запроса?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000010"), "INCLUDE хранит payload-колонки, не участвующие в поисковом ключе, и может позволить index-only scan без расширения семантики ключа. Цена — больший индекс, больше WAL и стоимость updates. Реальная выгода зависит от visibility map: если heap pages не all-visible, чтение heap всё равно потребуется.", "Когда INCLUDE в PostgreSQL-индексе полезен?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000011"), "MVCC-видимость обычно хранится в heap, поэтому executor проверяет visibility map. Если страницы недавно изменялись и не помечены all-visible после vacuum, приходится читать heap. Также план может выбрать другой путь из-за cost, низкой селективности, размера индекса или устаревшей статистики.", "Что мешает index-only scan, даже если все нужные колонки есть в индексе?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000012"), "Partial index полезен для небольшого часто запрашиваемого подмножества, например active rows, уменьшая размер и write cost. Planner использует его только если может доказать, что WHERE запроса подразумевает predicate индекса. Параметризованное или иначе сформулированное условие может помешать доказательству.", "Когда partial index лучше полного и какой у него главный подводный камень?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000013"), "Они индексируют результат выражения, например lower(email), чтобы запрос с тем же выражением использовал B-tree. Выражение должно быть immutable относительно строки; иначе индекс перестанет соответствовать данным. Цена вычисляется при insert/update, а синтаксис запроса должен совпадать распознаваемым образом.", "Для чего нужны expression indexes и почему функция должна быть подходящей?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000014"), "Обычная статистика считает колонки в основном независимо, поэтому коррелированные predicates дают ошибочную cardinality. CREATE STATISTICS может собирать dependencies, ndistinct или MCV для группы колонок. Это улучшает выбор join/order, но не заменяет актуальный ANALYZE и не собирает статистику между разными таблицами.", "Как extended statistics исправляют ошибки оценки planner?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000015"), "Nested loop хорош для малого outer input и индексного поиска во inner. Hash join эффективен для больших equality joins при достаточном work_mem; spill замедляет его. Merge join использует отсортированные входы и полезен для больших упорядочиваемых наборов или range-подобных условий. Решение зависит от оценок cardinality.", "Чем nested loop, hash join и merge join отличаются по условиям эффективности?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000016"), "work_mem применяется на каждый sort/hash node и потенциально на каждого parallel worker, поэтому один запрос может потребить его многократно, а множество сессий — исчерпать RAM. Малое значение вызывает temp spill. Настраивают глобально умеренно, а для известных аналитических операций — локально в транзакции после измерения.", "Как work_mem влияет на sort/hash и почему нельзя просто поставить большое значение глобально?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000017"), "Это число строк, прочитанных узлом, но отброшенных его filter; большое значение может указывать на плохой access path или отсутствующий подходящий индекс. Однако для маленькой таблицы sequential scan может быть дешевле. Смотрят actual loops, buffers, время и отношение estimated к actual rows в контексте всего плана.", "Что означает Rows Removed by Filter в EXPLAIN ANALYZE?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000018"), "ANALYZE реально выполняет statement, поэтому UPDATE/DELETE/INSERT изменит данные и может долго блокировать. Его запускают в BEGIN с последующим ROLLBACK, на безопасной копии или используют EXPLAIN без ANALYZE. Даже SELECT с ANALYZE создаёт нагрузку и может повлиять на production latency.", "Почему EXPLAIN ANALYZE опасно запускать на изменяющем запросе?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000019"), "Для распределения с сильным skew оптимальный plan зависит от значения параметра. После нескольких запусков PostgreSQL может выбрать generic plan, средний по стоимости, но плохой для редких значений. Проверяют custom/generic behavior, статистику и при необходимости меняют форму запроса, plan_cache_mode или разделяют сценарии.", "Как параметризованный prepared statement может получить неудачный generic plan?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000020"), "Ожидающие locks образуют очередь, и одна длинная транзакция может блокировать множество запросов; новые запросы иногда встают за уже ожидающим сильным lock. Сначала находят root blocker, его операцию и возможность безопасного rollback. Kill освобождает locks, но откат может быть долгим и повториться без устранения причины.", "Что такое lock queue и почему kill блокирующей сессии не всегда первый правильный шаг?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000021"), "Deadlock — цикл ожиданий, который PostgreSQL обнаруживает после deadlock_timeout и прерывает одну транзакцию; обычное ожидание имеет потенциального освобождающего владельца. Анализируют server log, pg_locks, pg_stat_activity и порядок захвата ресурсов. Исправляют единым порядком locks, короткими транзакциями и точными predicates.", "Как диагностировать deadlock и чем он отличается от обычного lock wait?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000022"), "Он блокирует выбранные строки от конкурентного изменения и подходит для read-modify-write. Для нескольких workers применяют FOR UPDATE SKIP LOCKED, понимая, что это даёт неполный снимок, но хорошо распределяет jobs. Оптимистичная версия/conditional update может быть лучше при редких конфликтах.", "Когда SELECT FOR UPDATE нужен и какие альтернативы есть для очереди работ?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000023"), "PostgreSQL использует Serializable Snapshot Isolation и отслеживает опасные зависимости, не превращая все чтения в blocking locks. При возможной аномалии одна транзакция завершается serialization_failure. Клиент должен повторить всю транзакцию с новым snapshot, ограниченно и только если её внешние side effects безопасны.", "Как уровень Serializable реализован в PostgreSQL и что обязан делать клиент?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000024"), "Каждый statement получает новый snapshot на начало statement, поэтому committed изменения между запросами становятся видимыми. Это нормальная гарантия уровня, а не ошибка MVCC. Если бизнес-инвариант требует стабильного snapshot, используют Repeatable Read/Serializable или формулируют операцию одним atomic statement.", "Почему Read Committed может видеть разные данные в двух SELECT одной транзакции?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000025"), "Они дают application-defined ключ и не привязаны автоматически к строке, поэтому все участники обязаны следовать одному протоколу. Transaction-level locks освобождаются при завершении транзакции и обычно безопаснее session-level. Нужно избегать коллизий ключей, держать lock коротко и не считать его заменой database constraints.", "Как advisory locks использовать безопасно?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000026"), "INSERT ... ON CONFLICT атомарно использует unique constraint для insert/update и устраняет check-then-act race. Но update expression всё равно должен сохранять бизнес-инвариант, а несколько связанных строк требуют транзакции или другого constraint. Неверный conflict target и side effects вне БД остаются проблемой.", "Как UPSERT с ON CONFLICT помогает конкурентности и где остаются гонки?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000027"), "Ключ должен поддерживать pruning основных запросов, lifecycle данных и равномерное распределение. Временной range удобен для retention, hash — для распределения, list — для ограниченных доменов. Слишком много partition увеличивает planning/metadata overhead, а unique constraint обычно должен включать partition key.", "Как выбрать partition key для большой таблицы?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000028"), "Она помогает, когда pruning исключает большую часть данных или облегчает maintenance, но запросы по другому ключу могут читать все partitions. Индексы всё равно нужны, joins и planning усложняются, skew создаёт hot partition. Сначала подтверждают проблему размера, retention или contention.", "Почему partitioning не является универсальным способом ускорить запросы?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000029"), "Если таблица partitioned по времени, detach/drop старой partition почти мгновенно освобождает логический объём и избегает миллионов row deletes/WAL. Без partitioning удаляют небольшими batches с паузами и vacuum, контролируя replicas и locks. Большая одиночная DELETE создаёт bloat и длительную транзакцию.", "Как безопасно удалять старые данные из очень большой временной таблицы?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000030"), "Physical streaming передаёт WAL на уровне кластера, хорошо подходит HA и read replicas той же major-совместимой системы. Logical публикует изменения выбранных таблиц и допускает иной layout/частичные наборы и upgrade-сценарии, но имеет ограничения DDL, sequences и конфликтов. Обе обычно асинхронны и могут отставать.", "Чем streaming replication отличается от logical replication?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000031"), "RPO — допустимая потеря данных; async replica имеет ненулевой RPO, synchronous commit может приблизить его к нулю ценой latency/availability. RTO — время обнаружения, promotion, routing и восстановления приложения. Репликация без протестированного failover, fencing и backup не даёт полного HA.", "Что означают RPO и RTO для PostgreSQL HA?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000032"), "Успешно записанный архив может быть неполным, несовместимым, повреждённым или не включать нужный WAL для PITR. Регулярный автоматизированный restore проверяет целостность, время восстановления и инструкции. Реплика не заменяет backup, потому что логическое удаление или corruption реплицируется.", "Почему backup нельзя считать рабочим без restore-теста?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000033"), "Изменения сначала записываются в WAL для durability и recovery, а затем страницы данных сбрасываются отдельно. Большие updates, indexes и full-page images увеличивают объём WAL, I/O и lag replicas. Измеряют WAL generation, checkpoint behavior и network; отключать durability ради скорости можно только при явном принятии потери.", "Как WAL влияет на write throughput и репликацию?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000034"), "Checkpoint вынуждает сбрасывать множество dirty pages и после него первые изменения страниц могут генерировать full-page images. Если max_wal_size мал или нагрузка велика, I/O становится bursty. Настраивают checkpoint_timeout, max_wal_size и completion_target, наблюдая write latency и объём WAL.", "Почему слишком частые checkpoints создают latency spikes?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000035"), "Каждое backend connection — процесс с памятью и потенциальным work_mem, поэтому тысячи idle connections дороги. Pooler ограничивает активные backend и мультиплексирует клиентов; transaction pooling несовместим с session state, temp tables и некоторыми prepared statements. Размер пула связывают с CPU и пропускной способностью, а не числом HTTP-запросов.", "Как connection pooling влияет на max_connections и память PostgreSQL?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000036"), "Клиент получает разные backend между транзакциями, поэтому session-level SET, advisory locks, temp tables, LISTEN и некоторые prepared statement assumptions ломаются. Приложение должно задавать нужное состояние transaction-local или отказаться от этих функций. Это цена высокой эффективности мультиплексирования.", "Какие проблемы создаёт PgBouncer в transaction pooling mode?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000037"), "BRIN хранит summary диапазонов страниц и очень мал, поэтому хорош для огромных append-mostly таблиц, где значение физически коррелирует с порядком, например timestamp. Он возвращает lossy ranges и хуже для случайно распределённых точечных поисков. pages_per_range балансирует размер и точность.", "Когда BRIN индекс лучше B-tree?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000038"), "GIN инвертирует элементы и обычно быстрее ищет containment/full-text, но дороже обновляется и может иметь pending list. GiST хранит обобщённое дерево, поддерживает distance/nearest-neighbor и разные операторные классы, часто с lossy recheck. Выбор определяется операторами, update rate и измерением.", "Как выбрать GIN или GiST для полнотекстового поиска и сложных типов?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000039"), "Если conversion требует rewrite, PostgreSQL переписывает все строки под сильной блокировкой и генерирует WAL. Для большой таблицы применяют expand-contract: новую колонку, backfill batches, dual write, проверку и переключение. Некоторые бинарно совместимые изменения metadata-only, но это проверяют для конкретной версии.", "Почему изменение типа колонки может заблокировать таблицу надолго?", "PostgreSQL" },
                    { new Guid("40000000-0000-0000-0000-000000000040"), "Сравнивают старый и новый plan, estimated/actual rows, статистику и распределение значений; проверяют ANALYZE, bloat, новые параметры и generic plans. Увеличивают statistics target для skewed колонок или создают extended statistics, затем исправляют запрос/индекс. Принудительный hint-подход не заменяет корректную модель cost.", "Как расследовать внезапное ухудшение плана после роста данных?", "PostgreSQL" },
                    { new Guid("50000000-0000-0000-0000-000000000006"), "Bounded context — граница модели и языка, где термины имеют однозначный смысл; это логическая граница DDD. Микросервис — deployment и operational boundary. Один сервис может временно содержать несколько контекстов, а один контекст иногда разворачивается несколькими компонентами; связь выбирают по ownership, coupling и независимости изменений.", "Как отличить bounded context от микросервиса?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000007"), "Invariant — правило, которое должно быть истинно после каждой успешной команды. Aggregate root сериализует изменения внутри своей границы и проверяет правила в одной транзакции. Если граница включает всё связанное, возникает огромный lock/graph; между агрегатами применяют ссылки по id и eventual consistency с компенсацией.", "Что такое invariant и почему именно он определяет транзакционную границу агрегата?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000008"), "Когда бизнес допускает промежуточное состояние и имеет ясное окно, статус и способ разрешения конфликта: например заказ принят, резерв ожидается. Пользователь должен видеть pending/failed, процесс — быть идемпотентным и наблюдаемым. Если нарушение правила даже на мгновение недопустимо, данные принадлежат одной strong-consistency границе.", "Когда eventual consistency является корректной бизнес-семантикой, а не техническим оправданием?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000009"), "Saga разбивает процесс на локальные транзакции и компенсирующие действия. Orchestrator явно хранит состояние и посылает команды, упрощая наблюдаемость сложного workflow; choreography связывает сервисы событиями и лучше для простого процесса, но легко создаёт скрытый граф. Компенсация — новая бизнес-операция, а не магический rollback.", "Как Saga координирует распределённый бизнес-процесс и в чём отличие orchestration от choreography?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000010"), "Она связывает availability и latency участников, усложняет recovery и часто не поддерживается внешними системами. Outbox, idempotency и saga дают локальную атомарность и явное промежуточное состояние. Distributed transaction допустима в ограниченной инфраструктуре с измеренной ценой, но не должна скрывать отсутствие бизнес-политики отказа.", "Почему distributed transaction редко является лучшим способом связать сервисы?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000011"), "Если изменение внутренней модели одного постоянно заставляет менять другой, общий контракт содержит чужие сущности или low-level слой диктует use case, зависимость направлена не по policy. Стабильные бизнес-правила должны зависеть от абстракций, а детали реализовывать их. Метрики coupling помогают, но решающим остаётся ownership причин изменения.", "Как определить, что два модуля имеют неправильное направление зависимости?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000012"), "Она направляет зависимости к policy, изолирует use cases от UI, БД и frameworks и облегчает тестирование заменяемых деталей. Она не создаёт правильную доменную модель, производительность или распределённую надёжность автоматически. Чрезмерное число pass-through слоёв и generic abstractions может увеличить ceremony без реальной независимости.", "Что Clean Architecture гарантирует, а чего не гарантирует?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000013"), "Write-side repository восстанавливает aggregate root для выполнения поведения и скрывает persistence. Read use case не обязан материализовать агрегат: проекция DTO может обращаться к оптимизированному query service/read model. Смешивание IQueryable в доменный контракт выдаёт детали хранения и позволяет обходить границы агрегата.", "Когда repository должен возвращать агрегат, а когда специализированный DTO?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000014"), "Domain event фиксирует факт внутри модели; handlers могут обновить локальное состояние до commit или подготовить outbox. Порядок, повторный вызов и ошибка должны иметь определённую семантику. Для внешних подписчиков событие преобразуют в integration event и публикуют после атомарной записи, а не отправляют из агрегата.", "Как применять domain events внутри одного процесса, не превращая их в ненадёжную интеграцию?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000015"), "Сначала проверяют, действительно ли правило должно быть атомарным. Если да, возможно граница агрегата неверна или нужна database constraint/одна транзакция application service. Если допускается задержка, команда меняет один агрегат и запускает process manager; конфликты и компенсации становятся частью модели.", "Как выбрать consistency boundary для команды, меняющей несколько агрегатов?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000016"), "Единый язык связывает разговор с экспертом, модель, команды, события и код, уменьшая перевод и неоднозначность. Один термин не должен означать разные вещи внутри context, а разные понятия не маскируются общим DTO. Изменение языка — сигнал уточнить модель, а не просто переименовать классы.", "В чём практическая ценность ubiquitous language?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000017"), "Если entities — набор setters, а правила размазаны по services, инварианты легко обходятся и модель анемична. Rich model полезна для сложного поведения и жизненного цикла. В простом CRUD bounded context сложность домена мала, и попытка искусственно добавить методы и aggregates только увеличит ceremony.", "Как распознать anemic domain model и всегда ли она плоха?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000018"), "Когда доменные границы ещё уточняются, команда невелика и независимый deployment не окупает distributed cost. Модули получают private data/schema ownership, явные contracts и dependency tests, оставаясь в одном процессе и deployment. Это не слоистый монолит: границы должны быть реальными, чтобы при необходимости выделиться.", "Когда modular monolith является лучшей стартовой архитектурой?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000019"), "Независимый ownership и cadence, отдельное масштабирование, security/isolation, иной availability requirement или стабильная bounded-context граница. Размер кода сам по себе слабый аргумент. До выделения оценивают distributed transactions, latency, observability, on-call и стоимость versioned contracts.", "Какие сигналы действительно оправдывают выделение микросервиса?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000020"), "Компоненты связаны не только ссылками, но и общим значением, порядком, алгоритмом, временем или идентичностью. Чем сильнее и дальше connascence, тем дороже изменение. Сильные формы стараются держать локально, а через удалённые границы оставлять явные стабильные контракты и минимальные временные предположения.", "Что такое connascence и как она помогает оценивать coupling?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000021"), "Контракт делают ориентированным на capability, добавляют optional поля, сохраняют семантику и применяют tolerant reader. Breaking change получает новую версию с периодом coexistence и telemetry использования старой. Внутреннюю entity не сериализуют напрямую, иначе каждое изменение модели становится внешним.", "Как спроектировать API для эволюции без бесконечного версионирования?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000022"), "Все retries одного намерения должны нести один ключ, иначе сервер не отличит повтор от новой операции. Сервер атомарно сохраняет ключ, fingerprint запроса и результат в ограниченном scope пользователя/операции. Повтор с тем же ключом и другим payload отклоняется, а retention соответствует окну повторов.", "Почему idempotency key должен быть связан с бизнес-операцией, а не случайной HTTP-попыткой?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000023"), "Timeout ограничивает одну попытку, retry повторяет вероятно транзиентный сбой, circuit breaker временно прекращает вызовы к явно нездоровой зависимости. Вместе они защищают ресурсы, но неверные настройки умножают нагрузку. Нужны общий deadline, jitter, ограничение конкуренции и ясная fallback-семантика.", "Как circuit breaker отличается от retry и timeout?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000024"), "Bulkhead разделяет ограниченные ресурсы, чтобы отказ одного workload/tenant/dependency не исчерпал все threads, connections или queue capacity. Это могут быть отдельные pools, semaphores, queues или deployments. Границы выбирают по failure domain и SLO; слишком мелкое деление снижает utilization.", "Что такое bulkhead и где его размещать?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000025"), "Когда downstream насыщен, upstream должен замедлиться, получить явный reject/429 или сбросить нагрузку по политике, а не бесконечно накапливать memory и queues. Bounded buffers, concurrency limits и deadlines задают пределы на каждом участке. Retry учитывает сигнал и не превращает перегрузку в storm.", "Как backpressure должна проходить через многоуровневую систему?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000026"), "SLI — измеряемая доля хороших событий, например запросы быстрее 300 мс без 5xx; SLO — целевая доля за окно. Error budget — допустимый остаток неуспеха, который связывает reliability с темпом изменений. Метрика должна отражать пользовательский outcome и исключать только заранее определённые случаи.", "Как сформулировать SLI, SLO и error budget для API?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000027"), "Среднее скрывает tail, который определяет опыт многих пользователей и усиливается при fan-out: максимум нескольких downstream растёт. Смотрят p50/p95/p99, распределение, saturation и ошибки по endpoint/tenant. Оптимизация tail часто требует limits, кэша, устранения очередей и медленных зависимостей.", "Почему средняя latency недостаточна для архитектурных решений?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000028"), "Trace связывает causality через сервисы и очереди, показывает critical path и fan-out. Sampling может пропустить редкие ошибки, clock/async boundaries и неверная propagation искажают картину, а наличие span не доказывает причину. Traces дополняют metrics, logs и профили, а не заменяют их.", "Как распределённая трассировка помогает и где может ввести в заблуждение?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000029"), "Модель выбирают по риску и масштабу: shared tables с tenant key, schema-per-tenant или database-per-tenant. Нужны защита от cross-tenant query, квоты, encryption/audit и план noisy neighbor. Часто применяют tiers: общая инфраструктура для большинства и выделенная для регулируемых клиентов.", "Как проектировать multi-tenant систему с разным уровнем изоляции?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000030"), "Приложение сначала читает кэш, при miss — источник и заполняет кэш; это просто и устойчиво к падению кэша. Между write и invalidation возможны stale reads, stampede и race с поздним заполнением. TTL, versioned keys, single-flight и событие invalidation уменьшают риск, но consistency остаётся явной.", "Какие компромиссы у cache-aside?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000031"), "Используют per-key request coalescing/single-flight, jittered TTL, background refresh и stale-while-revalidate. Для критичных ключей можно краткий distributed lock, но нужен timeout и fallback. Предварительный прогрев помогает известным hot keys; бесконечный retry к источнику при miss усугубляет отказ.", "Как бороться с cache stampede?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000032"), "Когда история изменений является бизнес-ценностью, нужны temporal queries/audit, сложные процессы или восстановление новых projections. Цена — эволюция событий, replay, storage, eventual consistency и иной способ исправления ошибок. Если нужен только audit log, обычная модель плюс неизменяемый журнал часто проще.", "Когда event sourcing оправдан?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000033"), "Старые события остаются фактом и обычно не переписываются. Read path применяет upcasters или handlers нескольких версий, а новые writers выпускают новую совместимую версию. Миграция snapshot/projection отделена; каждый replay тестируют на полном историческом наборе и детерминированных dependencies.", "Как изменять схему событий в event-sourced системе?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000034"), "Snapshot — производительная оптимизация, не источник истины. Его делают после измеренного числа событий или стоимости fold, версионируют вместе с моделью и умеют отбросить/rebuild. Слишком частые snapshots увеличивают writes, слишком редкие — recovery latency; важнее сохранить корректность replay.", "Как выбрать snapshot frequency в event sourcing?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000035"), "ACL переводит модель внешней или legacy-системы в язык собственного bounded context и не даёт чужим понятиям проникнуть внутрь. Это adapters, translators и policy, а не только HTTP client wrapper. Цена дополнительного кода окупается, когда внешняя модель нестабильна, неоднозначна или имеет другой жизненный цикл.", "Что такое anti-corruption layer?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000036"), "Он фиксирует bounded contexts и отношения upstream/downstream: partnership, customer-supplier, conformist, ACL, published language и другие. Это делает зависимости и власть над контрактом явными. Карта должна отражать организационную реальность ownership, иначе желаемая схема быстро расходится с кодом.", "Как context map помогает проектировать взаимодействие команд?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000037"), "Сервисы обходят API друг друга, связываются схемой и транзакциями, миграции требуют координации, а ownership данных размывается. Даже read-only доступ создаёт скрытый контракт. Переход возможен через выделение владельца таблиц, published views/events и постепенное прекращение прямых writes.", "Почему shared database между сервисами опасна?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000038"), "Трафик и capabilities переносят небольшими вертикальными срезами через facade/router, сохраняя работающий legacy для остального. Нужны ownership данных, синхронизация и критерий выключения старого пути. Простое дублирование функций без удаления legacy создаёт две постоянные системы и больший риск.", "Как strangler pattern снижает риск замены legacy-системы?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000039"), "ADR кратко фиксирует контекст, решение, альтернативы, последствия и статус на момент выбора. Он объясняет почему, а не пересказывает реализацию, и обновляется новым ADR при пересмотре. Записывают значимые труднообратимые решения; документ хранится рядом с кодом и связан с измеримыми ограничениями.", "Как architecture decision record должен помогать, а не превращаться в бюрократию?", "Architecture" },
                    { new Guid("50000000-0000-0000-0000-000000000040"), "Сравнивают не только лицензию, но и time-to-value, операционную зрелость, integration cost, lock-in, compliance, roadmap и стоимость владения/миграции. Строить стоит для дифференцирующей capability или уникальных требований; commodity чаще покупают. Решение включает exit strategy и proof of concept главного риска.", "Как оценивать build versus buy для критичного компонента?", "Architecture" }
                });
        }

